      "kind": "selectors",
      "name": "addCommitHandler:forPhase:",
      "framework": "QuartzCore",
      "feature_category": "Graphics, CoreAnimation, Color, HDR & IOSurface",
      "functionality": "Provides CoreAnimation compositor SPIs including CABackdropLayer, CAFilter, render server snapshots, commit phase handlers, and context IDs for out-of-process layer hosting.",
      "availability_3p": "apple-only-entitlement-or-daemon",
      "is_apple_only": true,
